import{_ as n,o as s,c as p,am as e}from"./chunks/framework._FJXuPhs.js";const m=JSON.parse('{"title":"SpringBoot项目部署方案","description":"","frontmatter":{"title":"SpringBoot项目部署方案","excerpt":"SpringBoot项目部署方案","date":"2024-01-11 08:42:29","updated":"2024-01-11 08:42:29"},"headers":[],"relativePath":"框架/框架 Spring家族/框架 SpringBoot/SpringBoot项目部署方案.md","filePath":"框架/框架 Spring家族/框架 SpringBoot/SpringBoot项目部署方案.md","lastUpdated":null}'),t={name:"框架/框架 Spring家族/框架 SpringBoot/SpringBoot项目部署方案.md"};function l(i,a,o,r,c,g){return s(),p("div",null,[...a[0]||(a[0]=[e(`<p>记录一些常用操作：</p><h3 id="_1、profiles指定不同环境的配置" tabindex="-1">1、profiles指定不同环境的配置 <a class="header-anchor" href="#_1、profiles指定不同环境的配置" aria-label="Permalink to &quot;1、profiles指定不同环境的配置&quot;">​</a></h3><p>一般用于区别不同的环境，常见的 开发、测试、正式</p><p>环境区分配置文件，可以通过两种方式：</p><ul><li><p>通过application.yml中编码指定 <code>profile.active=uat</code> 方式指定</p></li><li><p>通过mvn中profiles来区分不同环境对应的配置文件夹，人工可以手动在idea勾选生成不同环境的包(推荐)</p></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240623154801.png" alt="image.png"></p><p>如果是单元测试的话，可以通过 <code>@ActiveProfiles(&quot;test&quot;)</code> 注解的方式来指定配置文件。</p><h4 id="application-yml-编码指定" tabindex="-1">application.yml 编码指定 <a class="header-anchor" href="#application-yml-编码指定" aria-label="Permalink to &quot;application.yml 编码指定&quot;">​</a></h4><p>略</p><h4 id="mvn-→-profiles-区分" tabindex="-1">mvn → profiles 区分 <a class="header-anchor" href="#mvn-→-profiles-区分" aria-label="Permalink to &quot;mvn → profiles 区分&quot;">​</a></h4><p>在mvn中配置如下内容</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;profiles&gt;  </span></span>
<span class="line"><span>    &lt;profile&gt;  </span></span>
<span class="line"><span>        &lt;id&gt;node&lt;/id&gt;  </span></span>
<span class="line"><span>        &lt;properties&gt;  </span></span>
<span class="line"><span>            &lt;!--传递给脚本的参数值--&gt;  </span></span>
<span class="line"><span>            &lt;activeProfile&gt;node&lt;/activeProfile&gt;  </span></span>
<span class="line"><span>            &lt;package-name&gt;\${scripts_packageName}&lt;/package-name&gt;  </span></span>
<span class="line"><span>            &lt;boot-main&gt;\${scripts_bootMain}&lt;/boot-main&gt;  </span></span>
<span class="line"><span>        &lt;/properties&gt;  </span></span>
<span class="line"><span>        &lt;activation&gt;  </span></span>
<span class="line"><span>            &lt;activeByDefault&gt;true&lt;/activeByDefault&gt;  </span></span>
<span class="line"><span>        &lt;/activation&gt;  </span></span>
<span class="line"><span>    &lt;/profile&gt;  </span></span>
<span class="line"><span>    &lt;profile&gt;  </span></span>
<span class="line"><span>        &lt;id&gt;node1&lt;/id&gt;  </span></span>
<span class="line"><span>        &lt;properties&gt;  </span></span>
<span class="line"><span>            &lt;activeProfile&gt;node1&lt;/activeProfile&gt;  </span></span>
<span class="line"><span>            &lt;package-name&gt;\${scripts_packageName}&lt;/package-name&gt;  </span></span>
<span class="line"><span>            &lt;boot-main&gt;\${scripts_bootMain}&lt;/boot-main&gt;  </span></span>
<span class="line"><span>        &lt;/properties&gt;  </span></span>
<span class="line"><span>    &lt;/profile&gt;  </span></span>
<span class="line"><span>    &lt;profile&gt;  </span></span>
<span class="line"><span>        &lt;id&gt;node2&lt;/id&gt;  </span></span>
<span class="line"><span>        &lt;properties&gt;  </span></span>
<span class="line"><span>            &lt;activeProfile&gt;node2&lt;/activeProfile&gt;  </span></span>
<span class="line"><span>            &lt;package-name&gt;\${scripts_packageName}&lt;/package-name&gt;  </span></span>
<span class="line"><span>            &lt;boot-main&gt;\${scripts_bootMain}&lt;/boot-main&gt;  </span></span>
<span class="line"><span>        &lt;/properties&gt;  </span></span>
<span class="line"><span>    &lt;/profile&gt;  </span></span>
<span class="line"><span>&lt;/profiles&gt;</span></span></code></pre></div><p>看一下下面这个解释</p><p><strong>节点粗解：</strong></p><p><strong>id：</strong> 用来指定不同环境配置文件所在的目录:</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202401110850243.png" alt="image.png"></p><p>而在上面的代码中，在给定的配置中，定义了三个 <code>profile</code>，分别是 <code>node</code>, <code>node1</code>, 和 <code>node2</code>。每个 <code>profile</code> 中定义了一些 <code>properties</code>，这些属性可以在构建过程中使用</p><p><strong>properties：</strong></p><p>该节点中的节点是可作为参数传递给其他配置文件，上面代码中的package-name节点值可以在另外的assembly.xml或者shell脚本文件中通过<code>\${package-name}</code>获取到，如下</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202401110851350.png" alt="image.png"></p><p><strong>activeByDefault：</strong> 指定默认环境配置文件夹</p><p>↑ 看了一下大概的解释，这里的用法大概是在 pom 依赖配置文件中定义一下对应的 profile 的节点 id ；并配置对应文件夹（在 profiles 文件夹下）</p><p>通过不同的文件夹对应不同的 yml 配置文件</p><p>然后在打包或者运行的时候通过 类似这种命令来操作 <code>mvn clean install -Pnode1</code> ；具体待实践一下。</p><h3 id="_2、maven-assembly-plugin打-发布压缩包" tabindex="-1">2、maven-assembly-plugin打 发布压缩包 <a class="header-anchor" href="#_2、maven-assembly-plugin打-发布压缩包" aria-label="Permalink to &quot;2、maven-assembly-plugin打  发布压缩包&quot;">​</a></h3><p>先记录一下，具体没用过，暂时不太清楚</p><p>具体内容看参考链接： <a href="https://mp.weixin.qq.com/s/yGPnk-bTkcBUiVq2FZsrBQ" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/yGPnk-bTkcBUiVq2FZsrBQ</a></p><p>to be contined....</p><p>后续内容待实际部署的时候使用一下，再进行记录</p><h3 id="_3、idea-的配置文件指定环境" tabindex="-1">3、IDEA 的配置文件指定环境 <a class="header-anchor" href="#_3、idea-的配置文件指定环境" aria-label="Permalink to &quot;3、IDEA 的配置文件指定环境&quot;">​</a></h3><p>active profiles</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20250216074822.png" alt="image.png"></p><hr><p>参考</p><ul><li><a href="https://mp.weixin.qq.com/s/yGPnk-bTkcBUiVq2FZsrBQ" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/yGPnk-bTkcBUiVq2FZsrBQ</a></li></ul>`,35)])])}const h=n(t,[["render",l]]);export{m as __pageData,h as default};
